    base = e['price'] * e.get('quantity', 1)
    discount_bp = max(0, min(10000, e.get('discount_bp', 0)))

    net = _round_basis_points(base * (10000 - discount_bp), mode)
    tax = _round_basis_points(net * e.get('tax_bp', 0), mode)
    result = net + tax

    if e.get('kind') == 'refund':
        result = -result
    return result
